131	export type ResultV2 = { version: "2"; contentVersion: "2.0"; answers: number[]; score: number; level: number; capReasons: number[] };
132	export function validAnswersV2(value: unknown): value is number[] {
133	  return Array.isArray(value) && value.length === 10 && Array.from(value).every(v => Number.isInteger(v) && v >= 0 && v <= 4);
134	}
135	export function calculateResultV2(answers: readonly number[]): ResultV2 {
136	  if (!validAnswersV2(answers)) throw new Error("10개의 유효한 답변이 필요합니다.");
137	  const score = Math.round(answers.reduce((a, b) => a + b, 0) * 2.5);
138	  const base = scoreLevel(score);
139	  let allowed = 1;
140	  for (let candidate = 2; candidate <= 5; candidate++) {
141	    if (Object.entries(requirementsV2[candidate]).every(([axis, minimum]) => answers[Number(axis)] >= minimum)) allowed = candidate;
142	  }
143	  const level = Math.min(base, allowed);
144	  const capReasons = level < base ? Object.entries(requirementsV2[level + 1]).filter(([axis, minimum]) => answers[Number(axis)] < minimum).map(([axis]) => Number(axis)).sort((a,b) => a-b) : [];
145	  return { version: V2_VERSION, contentVersion: CONTENT_VERSION, answers: [...answers], score, level, capReasons };
146	}
147	export function parseSnapshotV2(value: unknown): ResultV2 | null {
148	  if (!value || typeof value !== "object") return null;
149	  const v = value as Record<string, unknown>;
150	  if (v.version !== V2_VERSION || v.contentVersion !== CONTENT_VERSION || !validAnswersV2(v.answers)) return null;
151	  const result = calculateResultV2(v.answers);
152	  if (v.score !== result.score || v.level !== result.level || JSON.stringify(v.capReasons) !== JSON.stringify(result.capReasons)) return null;
153	  return result;
154	}
155	export function parseDraftV2(raw: string, now = Date.now()): TestDraft | null {
156	  try { if (JSON.parse(raw).version !== V2_VERSION) return null; } catch { return null; }
157	  return parseLegacyDraft(raw, now);
158	}
