177	  const strengths = answers.map((stage, axis) => ({ stage, axis })).filter(x => x.stage >= 3).sort((a,b) => b.stage-a.stage || a.axis-b.axis).slice(0,2);
178	  const core = requirementsV2[Math.min(level + 1, 5)];
179	  const candidates = answers.map((stage, axis) => ({ axis, stage, target: Math.max(Math.min(level,4), core[axis] ?? 0), core: stage < (core[axis] ?? 0) }))
