181	  const guides = candidates.map(x => ({ ...x, current: questionsV2[x.axis].options[x.stage], action: String(questionsV2[x.axis].options[x.stage+1]), request: requests[x.axis][x.stage], boundary: boundaries[x.axis], maintenance: false }));
182	  if (level === 5 && guides.length === 0) {
183	    for (const axis of [9,7]) guides.push({ axis, stage: 4, target: 4, core: false, current: questionsV2[axis].options[4], action: axis === 9 ? "최근 실패 기록을 보고 검사와 규칙을 다시 점검해요." : "위험한 작업의 승인과 비용 한도를 계속 확인해요.", request: requests[axis][3], boundary: boundaries[axis], maintenance: true });
